H.background();
const f1 = 10;
const df = Math.max(0.5, P.df);
const f2 = f1 + df;
const tspan = 2.0;
const v = H.plot2d({ xMin: 0, xMax: tspan, yMin: -2.3, yMax: 2.3 });
v.grid(); v.axes();
const shift = (t * 0.3) % tspan;
const pts = [], envU = [], envD = [];
for (let i = 0; i <= 300; i++) {
  const x = tspan * i / 300;
  const tt = x + shift;
  const y = Math.sin(2 * Math.PI * f1 * tt) + Math.sin(2 * Math.PI * f2 * tt);
  pts.push([x, y]);
  const e = 2 * Math.cos(2 * Math.PI * (df / 2) * tt);
  envU.push([x, e]);
  envD.push([x, -e]);
}
v.path(envU, { color: H.colors.violet, width: 1.5, dash: [5, 4] });
v.path(envD, { color: H.colors.violet, width: 1.5, dash: [5, 4] });
v.path(pts, { color: H.colors.accent, width: 2 });
const fbeat = df;
const Tbeat = 1 / fbeat;
H.text("Beats: f_beat = |f1 - f2|", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Two close tones interfere; loudness throbs at the beat frequency", 24, 52, { color: H.colors.sub, size: 13 });
H.text("f1 = " + f1.toFixed(1) + " Hz   f2 = " + f2.toFixed(1) + " Hz   f_beat = " + fbeat.toFixed(1) + " Hz   T_beat = " + Tbeat.toFixed(2) + " s", 24, 74, { color: H.colors.sub, size: 13 });
